@code {
    private List<Channel>? channels;
    private int? activeChannelId;
    private Channel? activeChannel;
    private List<Message>? messages;
    private bool loadingMore;
    private bool allMessagesLoaded;
    private string newMessageText = "";
    private int? hoveredMessageId;
    private int? emojiPickerMessageId;

    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message>? threadMessages;
    private string threadReplyText = "";

    private ElementReference messageListRef;

    private const int PageSize = 30;

    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🔥", "👀"];

    // Track reply counts: rootMessageId -> count
    private readonly Dictionary<int, int> replyCountMap = new();

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannelAsync(channels[0]);
        }
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        if (activeChannelId == channel.Id) return;

        activeChannelId = channel.Id;
        activeChannel = channel;
        messages = null;
        allMessagesLoaded = false;
        replyCountMap.Clear();

        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        BuildReplyCountMap();

        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channels to clear unread badge
        channels = await ChatService.GetChannelsAsync();

        await ScrollToBottom();
    }

    private void BuildReplyCountMap()
    {
        if (messages is null) return;
        replyCountMap.Clear();
        foreach (var msg in messages)
        {
            if (msg.ReplyToId is int rootId)
            {
                replyCountMap.TryGetValue(rootId, out var count);
                replyCountMap[rootId] = count + 1;
            }
        }
    }

    private int GetReplyCount(int messageId) =>
        replyCountMap.TryGetValue(messageId, out var count) ? count : 0;

    private async Task OnMessageListScroll()
    {
        if (loadingMore || allMessagesLoaded || messages is null || activeChannelId is null) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop > 50) return;

        loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannelId.Value, messages.Count, PageSize);
        if (older.Count == 0)
        {
            allMessagesLoaded = true;
        }
        else
        {
            messages.InsertRange(0, older);
            BuildReplyCountMap();
        }

        loadingMore = false;
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(newMessageText) || activeChannelId is null) return;

        var msg = await ChatService.SendMessageAsync(activeChannelId.Value, newMessageText.Trim(), null);
        messages ??= new();
        messages.Add(msg);
        newMessageText = "";

        await ScrollToBottom();
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessageAsync();
        }
    }

    private async Task OpenThreadAsync(Message rootMessage)
    {
        // If the message is a reply, open the thread for its root
        var rootId = rootMessage.ReplyToId ?? rootMessage.Id;

        // Find the root message if we clicked on a reply
        if (rootMessage.ReplyToId is not null && messages is not null)
        {
            var root = messages.FirstOrDefault(m => m.Id == rootId);
            if (root is not null) rootMessage = root;
        }

        threadRootMessage = rootMessage;
        threadMessages = await ChatService.GetThreadAsync(rootId);
        threadReplyText = "";
        threadOpen = true;
        emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadMessages = null;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(threadReplyText) || threadRootMessage is null || activeChannelId is null) return;

        var reply = await ChatService.SendMessageAsync(activeChannelId.Value, threadReplyText.Trim(), threadRootMessage.Id);
        threadMessages ??= new();
        threadMessages.Add(reply);
        threadReplyText = "";

        // Update the reply count in the main view
        replyCountMap.TryGetValue(threadRootMessage.Id, out var count);
        replyCountMap[threadRootMessage.Id] = count + 1;
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        emojiPickerMessageId = emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task ReactAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        emojiPickerMessageId = null;

        // Refresh the message list to show updated reactions
        if (activeChannelId is not null && messages is not null)
        {
            messages = await ChatService.GetMessagesAsync(activeChannelId.Value, 0, messages.Count);
            BuildReplyCountMap();
        }

        // Also refresh thread if open
        if (threadOpen && threadRootMessage is not null)
        {
            threadMessages = await ChatService.GetThreadAsync(threadRootMessage.Id);
        }
    }

    private async Task ScrollToBottom()
    {
        await Task.Yield();
        await JS.InvokeVoidAsync("eval",
            "let el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight;");
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();

        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60)
        {
            var mins = (int)diff.TotalMinutes;
            return $"{mins} min{(mins == 1 ? "" : "s")} ago";
        }
        if (diff.TotalHours < 24)
        {
            var hours = (int)diff.TotalHours;
            return $"{hours} hour{(hours == 1 ? "" : "s")} ago";
        }
        if (diff.TotalDays < 7)
        {
            var days = (int)diff.TotalDays;
            return $"{days} day{(days == 1 ? "" : "s")} ago";
        }
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..(maxLength - 1)] + "…";
}

